// ── Connections ──────────────────────────────────────────────────────────────

/// The token of the connections the fake of the API answers ConnectSandbox with, and of
/// those its other answers hold.
const SANDBOX_TOKEN: &str = "sbc.test";
const SEEDED_TOKEN: &str = "sbc.seeded";

/// The sandbox the checks call at, and how long before its expiry a connection is no longer
/// used.
const KEY: &str = "sandbox-of-the-checks";
const MARGIN: Duration = Duration::from_secs(60);
const HOUR: Duration = Duration::from_secs(3600);

/// The codes after which a call made with a kept connection is made again on a new one.
const RETRIED: [(&str, u16, ErrorCode); 3] = [
    ("unauthenticated", 401, ErrorCode::Unauthenticated),
    ("permission_denied", 403, ErrorCode::PermissionDenied),
    ("not_found", 404, ErrorCode::NotFound),
];

/// A Connection to `url` with `token`, which expires `after` from now.
fn connection_to(url: &str, token: &str, after: Duration) -> wire::Connection {
    let expire = std::time::SystemTime::now() + after;
    let seconds = expire.duration_since(std::time::UNIX_EPOCH).unwrap().as_secs();
    let expire = buffa_types::google::protobuf::Timestamp {
        seconds: seconds as i64,
        ..Default::default()
    };
    wire::Connection {
        url: Some(url.to_owned()),
        token: Some(token.to_owned()),
        expire_time: Some(expire).into(),
        ..Default::default()
    }
}

/// The fake of the API: ConnectSandbox answers a connection to `server` for an hour, a call
/// whose answer holds a connection one to it of [`KEY`] that expires `seeded` from now, and
/// every other call nothing.
async fn api(server: &Fake, seeded: Duration) -> Fake {
    let url = server.url();
    Fake::new(move |call| match call.rpc.as_str() {
        "ConnectSandbox" => ok(&connection_to(&url, SANDBOX_TOKEN, HOUR)),
        "CreateSandbox" => ok(&wire::Sandbox {
            sandbox_id: Some(KEY.to_owned()),
            connection: Some(connection_to(&url, SEEDED_TOKEN, seeded)).into(),
            ..Default::default()
        }),
        "GetSandbox" => ok(&wire::Sandbox {
            sandbox_id: Some(KEY.to_owned()),
            connection: Some(connection_to(&url, SEEDED_TOKEN, seeded)).into(),
            ..Default::default()
        }),
        "ListSandboxes" => ok(&states::make(|message: &mut wire::ListSandboxesResponse| {
            message.sandboxes = vec![wire::Sandbox {
                sandbox_id: Some(KEY.to_owned()),
                connection: Some(connection_to(&url, SEEDED_TOKEN, seeded)).into(),
                ..Default::default()
            }]
        })),
        "UpdateSandbox" => ok(&wire::Sandbox {
            sandbox_id: Some(KEY.to_owned()),
            connection: Some(connection_to(&url, SEEDED_TOKEN, seeded)).into(),
            ..Default::default()
        }),
        "PauseSandbox" => ok(&wire::Sandbox {
            sandbox_id: Some(KEY.to_owned()),
            connection: Some(connection_to(&url, SEEDED_TOKEN, seeded)).into(),
            ..Default::default()
        }),
        "StopSandbox" => ok(&wire::Sandbox {
            sandbox_id: Some(KEY.to_owned()),
            connection: Some(connection_to(&url, SEEDED_TOKEN, seeded)).into(),
            ..Default::default()
        }),
        "ResumeSandbox" => ok(&wire::Sandbox {
            sandbox_id: Some(KEY.to_owned()),
            connection: Some(connection_to(&url, SEEDED_TOKEN, seeded)).into(),
            ..Default::default()
        }),
        "DeleteSandbox" => ok(&wire::Sandbox {
            sandbox_id: Some(KEY.to_owned()),
            connection: Some(connection_to(&url, SEEDED_TOKEN, seeded)).into(),
            ..Default::default()
        }),
        _ => empty(),
    })
    .await
}

/// A connection to `server`, answered by the fake of the API once: where the client is to
/// call, and the fake's call.
async fn connecting(server: std::net::SocketAddr) -> (std::net::SocketAddr, tokio::task::JoinHandle<Taken>) {
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let connection = connection_to(&format!("http://{server}"), SANDBOX_TOKEN, HOUR);
    let connects = tokio::spawn(async move { take(listener).await.answer(ok(&connection)).await });
    (address, connects)
}

/// A client of the fake of the API, as a user makes one.
fn client_of(api: &Fake) -> Client {
    Client::with_base_url(TOKEN, &api.url()).unwrap()
}

/// The call whose answer holds the connection of [`KEY`], which the fake of the API makes as
/// [`api`] says.
async fn seed(client: &Client) -> Result<(), Error> {
    client
        .create_sandbox(types::CreateSandboxRequest::default())
        .await
        .map(drop)
}

/// The call at a connection the checks make: at `key`, with `id` as its request_id, which the client fills
/// where it is empty.
async fn call(client: &Client, key: &str, id: &str) -> Result<types::Command, Error> {
    client
        .run_command(types::RunCommandRequest {
            sandbox_id: key.to_owned(),
            request_id: id.to_owned(),
            ..Default::default()
        })
        .await
}

/// The request of each call a fake took of [`call`].
fn sent(fake: &Fake) -> Vec<wire::RunCommandRequest> {
    fake.calls()
        .iter()
        .map(|call| wire::RunCommandRequest::decode_from_slice(&call.body).unwrap())
        .collect()
}

/// A fake of the server whose first `refusals` calls fail with `code`, and the others answer
/// nothing.
async fn refusing(refusals: usize, code: &'static str, status: u16) -> Fake {
    let mut left = refusals;
    Fake::new(move |_| {
        if left == 0 {
            return empty();
        }
        left -= 1;
        failure(code, status, &[], &STANDARD_NO_PAD)
    })
    .await
}

#[tokio::test]
async fn a_sandbox_is_connected_once() {
    let server = Fake::new(|_| empty()).await;
    let api = api(&server, HOUR).await;
    let client = client_of(&api);

    for _ in 0..2 {
        call(&client, KEY, "").await.unwrap();
    }

    assert_eq!(api.rpcs(), ["ConnectSandbox"]);
    assert_eq!(api.tokens(), [TOKEN]);
    // It names the sandbox, and nothing else: the sandbox decides its workspace.
    let connect = wire::ConnectSandboxRequest::decode_from_slice(&api.calls()[0].body).unwrap();
    let sandbox = wire::ConnectSandboxRequest {
        sandbox_id: Some(KEY.to_owned()),
        ..Default::default()
    };
    assert_eq!(connect, sandbox);
    assert_eq!(server.tokens(), [SANDBOX_TOKEN, SANDBOX_TOKEN]);
    assert!(
        server
            .calls()
            .iter()
            .all(|call| call.service == "SandboxRuntimeService")
    );
}
