#[tokio::test]
async fn a_kept_connection_refused_is_made_again_once() {
    for (code, status, expected) in RETRIED {
        let server = refusing(1, code, status).await;
        let api = api(&server, HOUR).await;
        let client = client_of(&api);

        seed(&client).await.unwrap();
        call(&client, KEY, "").await.unwrap();

        assert_eq!(api.rpcs(), ["CreateSandbox", "ConnectSandbox"], "{expected:?}");
        assert_eq!(server.tokens(), [SEEDED_TOKEN, SANDBOX_TOKEN], "{expected:?}");
        let [first, again] = <[_; 2]>::try_from(sent(&server)).unwrap();
        assert_eq!(first, again, "{expected:?}: the call made again is another request");
        request_id(first.request_id);
    }
}

