/// `Client::new` is the client over HTTPS: the build of the checks has a second TLS provider
/// (the manifest says why), and making it must not ask rustls for the process's default one.
#[tokio::test]
async fn a_client_prints_without_its_token() {
    let printed = format!("{:?}", Client::new(TOKEN));

    assert!(printed.contains("https://console.pethost.dev"), "{printed}");
    assert!(!printed.contains(TOKEN), "{printed}");
}

/// A client is shared between tasks, and a call may be awaited on another thread; a stream goes
/// to the task that reads it, by `next` or as a `Stream` of the `futures` crates.
#[tokio::test]
async fn a_client_and_its_calls_cross_threads() {
    fn shared<T: Clone + Send + Sync>() {}
    fn sent<T: Send>(_: &T) {}
    fn stream<T, S: futures_core::Stream<Item = Result<T, Error>> + Send + Unpin + 'static>(_: &S) {}

    shared::<Client>();
    shared::<Error>();

    let client = Client::new(TOKEN);
    sent(&async { client.get_workspace(types::GetWorkspaceRequest::default()).await });

    let mut responses = client.watch_sandbox_events(types::WatchSandboxEventsRequest::default());
    stream(&responses);
    sent(&responses.next());

    let mut responses = client.watch_command(types::WatchCommandRequest::default());
    stream(&responses);
    sent(&responses.next());

    let mut responses = client.watch_files(types::WatchFilesRequest::default());
    stream(&responses);
    sent(&responses.next());

    let mut responses = client.watch_conversation(types::WatchConversationRequest::default());
    stream(&responses);
    sent(&responses.next());
}

